Method.Source:
    /// <summary>
    /// Retrieves the first record of the table based on condition
    /// </summary>
    /// <param name = "_custAccount"> Customer account number</param>
    /// <param name = "_stateId">Licence state</param>
    /// <param name = "_type"> Licence type</param>
    /// <param name = "_licenceNumber"> Customer's licence number</param>
    /// <param name = "_forUpdate"> A Boolean value that determines whether the RecId of orign should be selected for update; optional.</param>
    /// <returns> The table record </returns>
    static METCustomerLicence find(CustAccount              _custAccount, 
                                   LogisticsAddressStateId  _stateId,
                                   METLicenceType           _type,
                                   METLicenceNumber         _licenceNumber,
                                   boolean                  _forUpdate = false)
    {
        METCustomerLicence customerLicence;

        if (_custAccount && _licenceNumber)
        {
            if (_forUpdate)
            {
                customerLicence.selectForUpdate(_forUpdate);
            }

            select firstonly customerLicence
                //index hint CustLiquorIdx
                where customerLicence.CustAccount   == _custAccount
                   && customerLicence.StateId       == _stateId
                   && customerLicence.Type          == _type
                   && customerLicence.LicenceNumber == _licenceNumber;
        }

        return customerLicence;
    }

/// <summary>
/// Searches for the first record of the table based on condition
/// </summary>
/// <param name = "_custAccount"> Customer account number</param>
/// <param name = "_stateId">Licence state</param>
/// <param name = "_type"> Licence type</param>
/// <param name = "_licenceNumber"> Customer's licence number</param>
/// <returns> A Boolean value "Yes" if record exists, else "No" </returns>
static boolean exist(CustAccount                _custAccount,
                     LogisticsAddressStateId    _stateId,
                     METLicenceType             _type,
                     METLicenceNumber           _licenceNumber)
{
    return _custAccount && _licenceNumber && (select firstonly RecId from METCustomerLicence
                                                //index hint CustLiquorIdx
                                                where METCustomerLicence.CustAccount    == _custAccount
                                                   && METCustomerLicence.StateId        == _stateId
                                                   && METCustomerLicence.Type           == _type
                                                   && METCustomerLicence.LicenceNumber  == _licenceNumber).RecId != 0;
}

    /// <summary>
    /// Validate write
    /// </summary>
    /// <returns>true if validation successful; otherwise, false</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();   

        if (ret && this.Type == METLicenceType::Liquor)
        {
            if (!this.StateId)
            {
                ret = checkFailed(strFmt("@SYS116347", fieldId2PName(tableNum(METCustomerLicence), fieldNum(METCustomerLicence, StateId))));
            }
            
            if (this.LicenceCategory == METLicenceCategory::Blank)
            {
                ret = checkFailed("@MET:LicenceCategoryValidation");
            }
        }

        return ret;
    }

    /// <summary>
    /// CB246_LicenseChecks set fields based on licence type
    /// </summary>
    /// <param name = "_fieldId">modified field id</param>
    public void modifiedField(FieldId _fieldId)
    {
        const str blank = '';
        
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCustomerLicence, Type) :
                if (this.Type == METLicenceType::Tobacco)
                {
                    this.StateId = blank;
                    this.LicenceCategory = METLicenceCategory::Blank;
                    this.IndustryIdentifier = blank;
                }
                else if (this.Type == METLicenceType::Liquor)
                {
                    this.LicenceCategory = METLicenceCategory::Retail;
                }
                break;
        }
    }

/// <summary>
/// Is it a tobacco licence?
/// </summary>
/// <returns>true if the licence type is Tobacco; otherwise, false</returns>
boolean isTobaccoLicence()
{
    return (this.Type == METLicenceType::Tobacco);
}

    /// <summary>
    /// Validate field
    /// </summary>
    /// <param name = "_fieldIdToCheck">Field Id to check</param>
    /// <returns>True if field successfully validated; otherwise, false</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch (_fieldIdToCheck)
        {
            case fieldNum(METCustomerLicence, StateId):     
                if (this.StateId)
                {
                    ret = LogisticsAddressState::METValidateStateId(this.StateId);
                }
                break;
        }
    
        return ret;
    }

    /// <summary>
    /// Init LicenceCategory to Blank as default type is tobacco
    /// </summary>
    public void initValue()
    {
        super();

        this.LicenceCategory = METLicenceCategory::Blank;
    }
